/* @autogenerated */
import { catchError, concat, concatMap, defer, from, map, mergeMap, Observable, of, take } from 'rxjs';
import { markErrorHandled } from '@shared/context/observability/error.service';
import { BatchResultErrorItem, LongTask, LongTaskStep } from '../long-task.model';
import { Slide } from './provider/repository-provider.interface';

/** Elementos por página al recorrer el listado de la selección. */
const PAGE_SIZE = 100;

let nextUid = 0;

/**
 * Claves de todos los elementos del listado `query`, recorriendo sus páginas. Se recogen todas antes de operar:
 * borrar o modificar mientras se pagina movería el cursor.
 */
export function collectKeys<F>(
  list: (query: F) => Observable<Slide<any>>,
  query: F,
  key: string,
): Observable<string[]> {
  const page = (current: F, keys: string[]): Observable<string[]> =>
    list(current).pipe(
      take(1),
      mergeMap((slide) => {
        const content = slide?.content ?? [];
        const all = [...keys, ...content.map((item) => item?.[key]).filter((value) => value !== undefined)];
        return slide?.hasNext && content.length && slide.next
          ? page({ ...query, limit: PAGE_SIZE, ...slide.next }, all)
          : of(all);
      }),
    );
  return defer(() => page({ ...query, limit: PAGE_SIZE }, [])).pipe(map((keys) => [...new Set(keys)]));
}

/**
 * Ejecuta `operation` clave a clave, en serie, para un backend sin operaciones masivas. Emite el progreso con la
 * misma forma que las tareas largas del servidor (un único paso `name`), así el diálogo de progreso lo muestra igual.
 *
 * El fallo de un elemento no detiene el resto: se anota en `errors` y no llega al aviso global. Si falla la obtención
 * de las claves, la tarea termina como `FAILED`.
 */
export function runLocalTask(
  name: string,
  keys: Observable<string[]>,
  operation: (key: string) => Observable<unknown>,
): Observable<LongTask> {
  return defer(() => {
    const uid = `local-${++nextUid}`;
    const startTime = new Date();
    let endTime: Date | undefined;
    const step: LongTaskStep = {
      name,
      stepStatus: 'PROCESSING',
      startTime,
      totalItems: 0,
      processedItems: 0,
      oks: [],
      warns: [],
      errors: [],
    };
    // Copias: el diálogo guarda los pasos que recibe
    const snapshot = (detailStatus: LongTask['detailStatus']): LongTask => ({
      uid,
      detailStatus,
      startTime,
      endTime,
      steps: [{ ...step, endTime, oks: [...step.oks], warns: [...step.warns], errors: [...step.errors] }],
    });
    const finish = (status: 'FINISHED' | 'FAILED') =>
      defer(() => {
        endTime = new Date();
        step.stepStatus = status;
        return of(snapshot(status));
      });

    const process = keys.pipe(
      take(1),
      mergeMap((list) => {
        step.totalItems = list.length;
        return concat(
          of(snapshot('PROCESSING')),
          from(list).pipe(
            concatMap((key) =>
              defer(() => operation(key)).pipe(
                take(1),
                map(() => {
                  step.oks.push(key);
                }),
                catchError((error) => {
                  markErrorHandled(error);
                  step.errors.push(toErrorItem(key, error));
                  return of(undefined);
                }),
                map(() => {
                  step.processedItems++;
                  return snapshot('PROCESSING');
                }),
              ),
            ),
          ),
          finish('FINISHED'),
        );
      }),
    );
    return concat(of(snapshot('PROCESSING')), process).pipe(
      catchError((error) => {
        markErrorHandled(error);
        return finish('FAILED');
      }),
    );
  });
}

function toErrorItem(item: string, error: any): BatchResultErrorItem {
  const code = readable(error?.status ?? error?.code ?? error?.name ?? 'error');
  const body = error?.error ?? error;
  const violations = Array.isArray(body)
    ? body
    : Array.isArray(body?.violations)
      ? body.violations
      : Array.isArray(body?.errors)
        ? body.errors
        : [];
  const wrongValues = violations.map((entry: any) => ({
    field: readable(entry?.field ?? entry?.propertyPath ?? entry?.property ?? ''),
    error: readable(entry?.description ?? entry?.message ?? entry?.violation ?? entry?.code ?? 'Invalid value'),
    wrong: readable(entry?.rejectedValue ?? entry?.wrong ?? entry?.value ?? ''),
  }));
  const violation =
    error?.message ??
    body?.message ??
    body?.detail ??
    body?.title ??
    (wrongValues.length ? 'Validation failed' : readable(body));
  return { item, fails: [{ code, violation: readable(violation), wrongValues }] };
}

function readable(value: unknown): string {
  if (value === undefined || value === null) return '';
  if (typeof value === 'string') return value;
  if (typeof value !== 'object') return String(value);
  try {
    return JSON.stringify(value);
  } catch {
    return Object.prototype.toString.call(value);
  }
}
